"""Synthetic full-evidence input sets for archive-free evidence-tier tests.

A plain checkout has only the committed runtime files, so acceptance with full evidence
cannot use the real archive in CI. These helpers derive a small, internally consistent
full-evidence input set from one committed runtime package instead. The AS/LC delivery
prefix, the nodes and the small carried files stay verbatim, a few LP edges are kept,
and every archive-only file (final claims, the original provenance map, its index and
shards, the split JSONL, full entity provenance, bundles and hierarchy files) is
regenerated so that the full LP checks hold. The receipt, LP summary and LP report are
rewritten to bind the regenerated bytes. The real package builder then seals the set
like any other input set; nothing here claims or records acceptance.
"""

# Standard Library
import hashlib
import json
import shutil

from collections import Counter
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Final, cast

# Package Library
from kgfegmcp.config import BackendSettings
from kgfegmcp.domain.identifiers import FrameworkId, SnapshotId
from kgfegmcp.packages.builder import build_graph_package
from kgfegmcp.packages.evidence import EvidenceVerifier
from kgfegmcp.packages.loader import GraphPackageLoader
from kgfegmcp.packages.models import PackageBuildSpec
from kgfegmcp.packages.repository import GraphPackageCandidate, GraphPackageRepository
from kgfegmcp.packages.validator import GraphPackageValidator
from kgfegmcp.profiles.repository import ProfileRepository

BASE_FRAMEWORK_ID: Final[str] = "nigeria-nerdc-mathematics-primary-1-3"
BASE_INPUT_SET: Final[str] = "nigeria_math"
KEPT_EDGES_PER_TYPE: Final[int] = 2
LP_LABELS: Final[tuple[str, str]] = ("buildsTowards", "relatesTo")
REPOSITORY_ROOT: Final[Path] = Path(__file__).resolve().parents[3]
SYNTHETIC_INPUT_SET: Final[str] = "synthetic_math"

# Carried files that stay byte-identical to the committed runtime package.
_CARRIED_DETAILED: Final[tuple[str, ...]] = (
    "as_lc_validation_report.json",
    "as_standards_framework.json",
    "as_unresolved_items.json",
    "lc_dedup_groups.json",
    "lc_generation_summary.json",
    "lp_unresolved_items.json",
)
_DECISIONS: Final[tuple[str, ...]] = (
    "buildsTowards",
    "needs_review",
    "no_relation",
    "relatesTo",
)
_PARTITION_ALGORITHM: Final[str] = "SHA256(UTF8(relationship_id))[0] modulo 64"
# Request identity fields every kept per-edge record shares with the final claims.
_REQUEST_FIELDS: Final[tuple[str, ...]] = (
    "candidate_pairs_content_hash",
    "candidate_summary_content_hash",
    "config_content_hash",
    "doc_key",
    "requests_content_hash",
    "upstream_content_hash",
)
_SPLIT_BASENAMES: Final[dict[str, str]] = {
    "buildsTowards": "lp_relationships_builds_towards.jsonl",
    "relatesTo": "lp_relationships_relates_to.jsonl",
}
# Wire property aliases back to detailed split-record field names.
_WIRE_FIELDS: Final[dict[str, str]] = {
    "attributionStatement": "attribution_statement",
    "author": "author",
    "dateCreated": "date_created",
    "dateModified": "date_modified",
    "description": "description",
    "license": "license",
    "provider": "provider",
    "sourceEntity": "source_entity",
    "sourceEntityValue": "source_entity_value",
    "targetEntity": "target_entity",
    "targetEntityValue": "target_entity_value",
}

Json = dict[str, Any]


# Project handle and the committed base package; classes follow their dependencies.
@dataclass(frozen=True, slots=True)
class SyntheticProject:
    """Locate one synthetic project: its config, input set and built package."""

    framework_id: FrameworkId
    input_dir: Path
    package_dir: Path
    project_dir: Path
    snapshot_id: SnapshotId

    @property
    def settings(self) -> BackendSettings:
        """Return settings rooted at the synthetic project.

        Returns
        -------
        BackendSettings
            Settings whose project, config and graph-package roots are the project's.
        """

        return BackendSettings(
            graph_packages_root_override=None, project_dir=self.project_dir
        )

    def candidate(self) -> GraphPackageCandidate:
        """Return the repository candidate for the synthetic package.

        Returns
        -------
        GraphPackageCandidate
            Safely discovered candidate.
        """

        return self.repository().candidate(
            framework_id=self.framework_id, snapshot_id=self.snapshot_id
        )

    def manifest(self) -> Json:
        """Read the synthetic package manifest.

        Returns
        -------
        Json
            Parsed manifest JSON.
        """

        return _read_json(self.package_dir / "package_manifest.json")

    def repository(self) -> GraphPackageRepository:
        """Return a package repository over the project's graph-package root.

        Returns
        -------
        GraphPackageRepository
            Repository rooted at ``data/graph_packages``.
        """

        return GraphPackageRepository(
            graph_packages_root=self.settings.graph_packages_root
        )

    def validator(self, *, evidence: bool) -> GraphPackageValidator:
        """Construct the production validator for the synthetic project.

        Parameters
        ----------
        evidence
            Whether the loader runs the evidence tier after the runtime tier.

        Returns
        -------
        GraphPackageValidator
            Validator wired exactly as ``kgfegmcp-validate-packages`` wires it.
        """

        repository = self.repository()
        loader = GraphPackageLoader(
            evidence_verifier=(
                EvidenceVerifier(project_dir=self.project_dir) if evidence else None
            ),
            profile_repository=ProfileRepository(
                profile_root=self.settings.profile_root
            ),
            repository=repository,
        )
        return GraphPackageValidator(loader=loader, repository=repository)


@dataclass(frozen=True, slots=True)
class _BasePackage:
    """Read files of the committed runtime package the synthetic set derives from."""

    root: Path

    def json(self, path: str) -> Json:
        """Parse one committed JSON file.

        Parameters
        ----------
        path
            Package-relative path.

        Returns
        -------
        Json
            Parsed object.
        """

        return _read_json(self.root / path)

    def path(self, logical_name: str) -> str:
        """Return the declared package path of one artifact.

        Parameters
        ----------
        logical_name
            Dedicated manifest artifact name.

        Returns
        -------
        str
            Package-relative path.
        """

        return cast(str, self.json("package_manifest.json")["artifacts"][logical_name])

    def read(self, path: str) -> bytes:
        """Read one committed file.

        Parameters
        ----------
        path
            Package-relative path.

        Returns
        -------
        bytes
            Exact bytes.
        """

        return (self.root / path).read_bytes()


# Encoding helpers.
def canonical_json(value: object) -> bytes:
    """Encode canonical JSON: sorted keys, compact, UTF-8 and one trailing newline.

    Parameters
    ----------
    value
        JSON-compatible value.

    Returns
    -------
    bytes
        Canonical bytes.
    """

    text = json.dumps(
        allow_nan=False,
        ensure_ascii=False,
        obj=value,
        separators=(",", ":"),
        sort_keys=True,
    )
    return (text + "\n").encode("utf-8")


def qualified_sha256(data: bytes) -> str:
    """Return the qualified ``sha256:<hex>`` digest of bytes.

    Parameters
    ----------
    data
        Bytes to hash.

    Returns
    -------
    str
        Qualified digest.
    """

    return "sha256:" + _raw_sha256(data)


def _raw_sha256(data: bytes) -> str:
    """Return the unqualified hexadecimal SHA-256 of bytes.

    Parameters
    ----------
    data
        Bytes to hash.

    Returns
    -------
    str
        Lowercase hexadecimal digest.
    """

    return hashlib.sha256(data).hexdigest()


def _read_json(path: Path) -> Json:
    """Parse one JSON object file.

    Parameters
    ----------
    path
        JSON file.

    Returns
    -------
    Json
        Parsed object.
    """

    return cast(Json, json.loads(path.read_bytes()))


def shard_number(identifier: str) -> int:
    """Return the provenance shard number for one relationship identifier.

    Parameters
    ----------
    identifier
        Exact relationship identifier.

    Returns
    -------
    int
        ``SHA256(UTF8(identifier))[0] modulo 64``.
    """

    return hashlib.sha256(identifier.encode("utf-8")).digest()[0] % 64


# Evidence regeneration, in the order an input set is assembled.
def _kept_edges(
    *, base: _BasePackage, edges_per_type: int
) -> tuple[dict[str, Json], dict[str, bytes]]:
    """Keep the AS/LC delivery prefix and the first LP edges of each type.

    Parameters
    ----------
    base
        Committed base package.
    edges_per_type
        Number of LP edges kept per relationship type, ordered by identifier.

    Returns
    -------
    tuple[dict[str, Json], dict[str, bytes]]
        Kept LP wire records by identifier, and the two delivery files by path.
    """

    nodes = base.path("nodes")
    relationships = base.path("relationships")
    delivery = base.read(relationships)
    prefix_bytes = base.json("detailed/lp_normalization_receipt.json")[
        "asLcRelationshipPrefixBytes"
    ]
    lines = [
        raw for raw in delivery[prefix_bytes:].splitlines(keepends=True) if raw.strip()
    ]
    kept_lines: list[bytes] = []

    # Delivery orders LP lines by (type, identifier); keep that order.
    for label in LP_LABELS:
        kept_lines.extend(
            sorted(
                (raw for raw in lines if json.loads(raw)["label"] == label),
                key=lambda raw: json.loads(raw)["identifier"],
            )[:edges_per_type]
        )

    kept = {json.loads(raw)["identifier"]: json.loads(raw) for raw in kept_lines}
    return kept, {
        f"delivery/{Path(nodes).name}": base.read(nodes),
        f"delivery/{Path(relationships).name}": delivery[:prefix_bytes]
        + b"".join(kept_lines),
    }


def _original_record(slim: Json) -> Json:
    """Re-inflate one slim LP record into an original-shaped full record.

    The archived fields get synthetic values: candidate evidence text, the admissible
    decisions (including the final one) and a producer judgment equal to the final one.

    Parameters
    ----------
    slim
        Committed slim per-edge record.

    Returns
    -------
    Json
        Full record without ``original_entry_sha256``.
    """

    record = {
        name: value for name, value in slim.items() if name != "original_entry_sha256"
    }
    claim = dict(record["claim"])
    judgment = claim["judgment"]
    candidate = dict(claim["candidate"])
    candidate["admissible_decisions"] = [
        {"decision": judgment["decision"], "direction": judgment["direction"]},
        {"decision": "no_relation", "direction": None},
    ]
    candidate["evidence"] = [
        {"text": f"Synthetic evidence for {candidate['pair_id']}."}
    ]
    claim["candidate"] = candidate
    claim["provenance"] = {**claim["provenance"], "producer_judgment": dict(judgment)}
    record["claim"] = claim
    return record


def _originals(*, base: _BasePackage, kept: dict[str, Json]) -> dict[str, Json]:
    """Re-inflate the kept edges' committed slim records into full records.

    Parameters
    ----------
    base
        Committed base package.
    kept
        Kept LP wire records by identifier.

    Returns
    -------
    dict[str, Json]
        Full per-edge records by identifier; all share one request identity.
    """

    originals = {
        identifier: _original_record(
            base.json(
                f"slim/lp_relationship_provenance_shard_{shard_number(identifier):02d}.json"
            )[identifier]
        )
        for identifier in sorted(kept)
    }
    first = originals[min(originals)]
    assert all(
        record[name] == first[name]
        for record in originals.values()
        for name in (
            *_REQUEST_FIELDS,
            "candidate_artifact_byte_hashes",
            "final_claims_content_hash",
        )
    ), "Kept LP records must share one request identity."
    return originals


def _no_relation_claim(*, base: _BasePackage, originals: dict[str, Json]) -> Json:
    """Build one synthetic nonpublishing claim between two unused standards.

    Parameters
    ----------
    base
        Committed base package supplying the standard CASE UUIDs.
    originals
        Kept full records, whose trace hashes the claim reuses.

    Returns
    -------
    Json
        Original-shaped ``no_relation`` claim.
    """

    used = {
        record["claim"][side]
        for record in originals.values()
        for side in ("source_sfi_uuid", "target_sfi_uuid")
    }
    rows = (json.loads(raw) for raw in base.read(base.path("nodes")).splitlines())
    first, second = sorted(
        row["properties"]["caseIdentifierUUID"]
        for row in rows
        if "StandardsFrameworkItem" in row["labels"]
        and row["properties"]["caseIdentifierUUID"] not in used
    )[:2]
    pair_id = "synthetic-no-relation-pair"
    judgment = {
        "confidence": 0.5,
        "decision": "no_relation",
        "direction": None,
        "first_sfi_uuid": first,
        "pair_id": pair_id,
        "rationale": "Synthetic nonpublishing judgment.",
        "second_sfi_uuid": second,
        "warnings": [],
    }
    template = originals[min(originals)]["claim"]["provenance"]
    return {
        "candidate": {
            "admissible_decisions": [{"decision": "no_relation", "direction": None}],
            "evidence": [{"text": "Synthetic nomination evidence."}],
            "first_sfi_uuid": first,
            "pair_id": pair_id,
            "second_sfi_uuid": second,
            "warnings": [],
        },
        "judgment": judgment,
        "provenance": {
            **template,
            "producer_judgment": dict(judgment),
            "request_id": "synthetic-request",
        },
        "source_sfi_uuid": None,
        "target_sfi_uuid": None,
    }


def _cycle_diagnostics(kept: dict[str, Json]) -> Json:
    """Return the acyclic topology facts of the kept ``buildsTowards`` edges.

    Parameters
    ----------
    kept
        Kept LP wire records by identifier.

    Returns
    -------
    Json
        Cycle diagnostics shared by final claims and the LP report.
    """

    builds = [edge for edge in kept.values() if edge["label"] == "buildsTowards"]
    endpoints = {
        edge["properties"][side]
        for edge in builds
        for side in ("sourceEntityValue", "targetEntityValue")
    }
    return {
        "components": [],
        "cyclic_component_count": 0,
        "cyclic_edge_count": 0,
        "cyclic_node_count": 0,
        "graph_edge_count": len(builds),
        "graph_node_count": len(endpoints),
    }


def _final_claims(
    *, base: _BasePackage, claims: list[Json], kept: dict[str, Json], record: Json
) -> bytes:
    """Serialize final claims bound to the kept records' request identity.

    Parameters
    ----------
    base
        Committed base package supplying the receipt, report and eligibility.
    claims
        Every final claim, publishing and nonpublishing.
    kept
        Kept LP wire records by identifier.
    record
        One kept full record carrying the shared request and model identity.

    Returns
    -------
    bytes
        Canonical ``lp_final_claims.json``.
    """

    report_hashes = base.json("detailed/lp_validation_report.json")[
        "input_content_hashes"
    ]
    eligibility = base.json("detailed/lp_generation_summary.json")["eligibility"]
    request_manifest = {
        **{name: record[name] for name in _REQUEST_FIELDS},
        "artifact_byte_hashes": record["candidate_artifact_byte_hashes"],
        "eligible_sfis_content_hash": eligibility["eligible_sfis_content_hash"],
        "framework_uuid": base.json("detailed/lp_normalization_receipt.json")[
            "frameworkCaseUuid"
        ],
        "pair_ids": [claim["candidate"]["pair_id"] for claim in claims],
        "request_ids": [claim["provenance"]["request_id"] for claim in claims],
        "total_candidate_pairs": len(claims),
        "total_requests": len(claims),
    }
    decisions = Counter(claim["judgment"]["decision"] for claim in claims)
    return canonical_json(
        {
            "checkpoint_receipt_byte_hash": report_hashes["checkpoint_receipt_bytes"],
            "claims": claims,
            "content_hash": record["final_claims_content_hash"],
            "cycle_diagnostics": _cycle_diagnostics(kept),
            "decision_counts": {name: decisions[name] for name in _DECISIONS},
            "execution_material": {
                "config_content_hash": report_hashes["effective_config"],
                "model_config": record["model_configuration"],
                "model_settings": record["model_settings"],
                "request_manifest": request_manifest,
            },
            "graph_status": "acyclic",
            "request_manifest": request_manifest,
            "total_claims": len(claims),
        }
    )


def _provenance_files(originals: dict[str, Json]) -> dict[str, bytes]:
    """Serialize the original map, its 64 canonical shards and the original index.

    Parameters
    ----------
    originals
        Full per-edge records by identifier.

    Returns
    -------
    dict[str, bytes]
        Files by full-evidence package path.
    """

    provenance = canonical_json(originals)
    files = {"detailed/lp_relationship_provenance.json": provenance}
    partitions: dict[str, Json] = {}

    for number in range(64):
        bucket = {i: r for i, r in originals.items() if shard_number(i) == number}
        path = f"additional/lp_relationship_provenance_shard_{number:02d}.json"
        files[path] = canonical_json(bucket)
        partitions[f"learningProgressionProvenanceShard{number:02d}"] = {
            "artifactPath": path,
            "entryCount": len(bucket),
            "sha256": qualified_sha256(files[path]),
        }

    files["detailed/lp_relationship_provenance_index.json"] = canonical_json(
        {
            "formatVersion": "1.0",
            "originalProvenanceLogicalName": "learningProgressionProvenance",
            "originalProvenanceSha256": qualified_sha256(provenance),
            "partitionAlgorithm": _PARTITION_ALGORITHM,
            "partitionCount": 64,
            "partitions": partitions,
        }
    )
    return files


def _split_record(*, line: Json, metadata: Json) -> Json:
    """Invert one delivered LP wire line into its detailed split record.

    Parameters
    ----------
    line
        Delivered LP relationship wire record.
    metadata
        Full per-edge provenance record carried as split metadata.

    Returns
    -------
    Json
        Detailed LP record whose expected wire form is ``line``.
    """

    properties = line["properties"]
    return {
        **{field: properties.get(alias) for alias, field in _WIRE_FIELDS.items()},
        "identifier": line["identifier"],
        "metadata": metadata,
        "relationship_type": line["label"],
        "source_entity_key": "caseIdentifierUUID",
        "target_entity_key": "caseIdentifierUUID",
    }


def _entity_files(base: _BasePackage) -> dict[str, bytes]:
    """Re-inflate full AS and LC entity provenance and add the checksummed AS files.

    Parameters
    ----------
    base
        Committed base package supplying the slim entity documents.

    Returns
    -------
    dict[str, bytes]
        Files by full-evidence package path, including the carried small files.
    """

    slim_as = base.json("slim/as_entity_provenance.json")
    slim_lc = base.json("slim/lc_entity_provenance.json")
    source = slim_lc["sourceDocument"]
    files = {
        "detailed/as_entity_provenance.json": canonical_json(
            {
                "framework": slim_as["sourceDocument"],
                "items": {
                    key: {
                        **{
                            n: v for n, v in item.items() if n != "original_item_sha256"
                        },
                        "candidate_source_refs": [f"synthetic-ref-{key}"],
                    }
                    for key, item in slim_as["items"].items()
                },
                "kg_run_manifest": {"synthetic": True},
            }
        ),
        "detailed/lc_entity_provenance.json": canonical_json(
            {
                "doc_key": source["doc_key"],
                "learning_components": {
                    key: {
                        n: v
                        for n, v in component.items()
                        if n != "original_component_sha256"
                    }
                    for key, component in slim_lc["learning_components"].items()
                },
                "pdf_name": source["pdf_name"],
            }
        ),
        # Archive-only AS files that acceptance only checksums.
        "detailed/as_kg_bundle.json": canonical_json({"synthetic": "AS bundle"}),
        "detailed/as_lc_kg_bundle.json": canonical_json({"synthetic": "AS-LC bundle"}),
        "detailed/as_relationships_has_child.jsonl": canonical_json({"synthetic": 1}),
        "detailed/as_standards_framework_items.jsonl": canonical_json({"synthetic": 2}),
    }
    files.update(
        {
            f"detailed/{name}": base.read(f"detailed/{name}")
            for name in _CARRIED_DETAILED
        }
    )
    return files


def _report_and_summary(
    *,
    base: _BasePackage,
    claims: list[Json],
    files: dict[str, bytes],
    kept: dict[str, Json],
) -> dict[str, bytes]:
    """Rewrite the LP report and summary for the kept edges and regenerated bytes.

    Parameters
    ----------
    base
        Committed base package supplying the original report and summary.
    claims
        Every final claim.
    files
        Regenerated files so far, by full-evidence package path.
    kept
        Kept LP wire records by identifier.

    Returns
    -------
    dict[str, bytes]
        Rewritten ``lp_validation_report.json`` and ``lp_generation_summary.json``.
    """

    report = base.json("detailed/lp_validation_report.json")
    summary = base.json("detailed/lp_generation_summary.json")
    decisions = Counter(claim["judgment"]["decision"] for claim in claims)
    edges = Counter(edge["label"] for edge in kept.values())
    report["cycle_diagnostics"] = _cycle_diagnostics(kept)
    report["object_counts"].update(
        {
            "builds_towards_claims": decisions["buildsTowards"],
            "builds_towards_relationships": edges["buildsTowards"],
            "candidate_pairs": len(claims),
            "final_claims": len(claims),
            "identifier_collisions": 0,
            "needs_review_claims": decisions["needs_review"],
            "no_relation_claims": decisions["no_relation"],
            "relates_to_claims": decisions["relatesTo"],
            "relates_to_relationships": edges["relatesTo"],
            "relationship_provenance": len(kept),
            "relationships": len(kept),
            "requests": len(claims),
            "unresolved_failed_pairs": 0,
        }
    )
    report_bytes = canonical_json(report)
    hashes = {
        **{
            path.rsplit("/", 1)[-1]: _raw_sha256(content)
            for path, content in files.items()
        },
        "lp_validation_report.json": _raw_sha256(report_bytes),
    }
    summary["decision_counts"] = {name: decisions[name] for name in _DECISIONS}
    summary["object_counts"].update(
        {
            **report["object_counts"],
            "accepted_claims": len(kept),
            "nonpublishing_claims": decisions["no_relation"]
            + decisions["needs_review"],
            "resolved_failure_attempts": report["object_counts"][
                "generation_failure_attempts"
            ],
        }
    )

    for field in ("artifact_byte_hashes", "input_artifact_byte_hashes"):
        summary[field] = {
            name: hashes.get(name, value) for name, value in summary[field].items()
        }

    return {
        "detailed/lp_generation_summary.json": canonical_json(summary),
        "detailed/lp_validation_report.json": report_bytes,
    }


def _receipt(
    *, base: _BasePackage, files: dict[str, bytes], kept: dict[str, Json]
) -> bytes:
    """Rewrite the normalization receipt to bind every other full-evidence file.

    Parameters
    ----------
    base
        Committed base package supplying the original receipt.
    files
        Every other full-evidence file by package path.
    kept
        Kept LP wire records by identifier.

    Returns
    -------
    bytes
        Canonical ``lp_normalization_receipt.json``.
    """

    receipt = base.json("detailed/lp_normalization_receipt.json")
    edges = Counter(edge["label"] for edge in kept.values())
    by_basename = {path.rsplit("/", 1)[-1]: content for path, content in files.items()}
    receipt["buildsTowardsRelationships"] = edges["buildsTowards"]
    receipt["relatesToRelationships"] = edges["relatesTo"]
    # The nodes and AS/LC prefix are unchanged, so their input hashes still hold.
    receipt["inputSha256"] = {
        name: (qualified_sha256(by_basename[name]) if name in by_basename else value)
        for name, value in receipt["inputSha256"].items()
    }
    receipt["outputSha256"] = {
        path: qualified_sha256(content) for path, content in sorted(files.items())
    }
    return canonical_json(receipt)


def _write_spec(
    *, input_dir: Path, input_set: str, nodes: str, relationships: str
) -> Path:
    """Write the committed base build spec with paths moved to the synthetic set.

    Parameters
    ----------
    input_dir
        Synthetic input-set directory.
    input_set
        Input-set directory name.
    nodes
        Delivery nodes basename.
    relationships
        Delivery relationships basename.

    Returns
    -------
    Path
        Written ``package_build.json``.
    """

    spec = _read_json(
        REPOSITORY_ROOT
        / "data"
        / "input_artifacts"
        / BASE_INPUT_SET
        / "package_build.json"
    )
    relative = f"data/input_artifacts/{input_set}"
    spec.update(
        {
            "additionalArtifacts": {
                f"learningProgressionProvenanceShard{n:02d}": (
                    f"{relative}/additional/lp_relationship_provenance_shard_{n:02d}.json"
                )
                for n in range(64)
            },
            "detailedArtifactsDirectory": f"{relative}/detailed",
            "nodes": f"{relative}/delivery/{nodes}",
            "outputRoot": "data/graph_packages",
            "relationships": f"{relative}/delivery/{relationships}",
        }
    )
    spec_path = input_dir / "package_build.json"
    spec_path.write_text(json.dumps(indent=2, obj=spec), encoding="utf-8")
    return spec_path


def write_synthetic_input_set(
    *,
    edges_per_type: int = KEPT_EDGES_PER_TYPE,
    input_set: str = SYNTHETIC_INPUT_SET,
    project_dir: Path,
) -> Path:
    """Write a consistent synthetic full-evidence input set and its build spec.

    Parameters
    ----------
    edges_per_type
        Number of delivered LP edges kept per relationship type.
    input_set
        Input-set directory name under ``data/input_artifacts``.
    project_dir
        Project root that will hold ``config/`` and ``data/``.

    Returns
    -------
    Path
        Path of the written ``package_build.json``.
    """

    base = _BasePackage(
        root=next(
            path
            for path in sorted(
                (
                    REPOSITORY_ROOT / "data" / "graph_packages" / BASE_FRAMEWORK_ID
                ).iterdir()
            )
            if path.is_dir() and not path.name.startswith(".")
        )
    )
    kept, files = _kept_edges(base=base, edges_per_type=edges_per_type)
    originals = _originals(base=base, kept=kept)
    claims = [originals[i]["claim"] for i in sorted(originals)]
    claims.append(_no_relation_claim(base=base, originals=originals))
    files["detailed/lp_final_claims.json"] = _final_claims(
        base=base, claims=claims, kept=kept, record=originals[min(originals)]
    )
    files.update(_provenance_files(originals))

    for label, basename in _SPLIT_BASENAMES.items():
        files[f"detailed/{basename}"] = b"".join(
            canonical_json(_split_record(line=kept[i], metadata=originals[i]))
            for i in sorted(kept)
            if kept[i]["label"] == label
        )

    files.update(_entity_files(base))
    files.update(_report_and_summary(base=base, claims=claims, files=files, kept=kept))
    files["detailed/lp_normalization_receipt.json"] = _receipt(
        base=base, files=files, kept=kept
    )
    input_dir = project_dir / "data" / "input_artifacts" / input_set

    for path, content in files.items():
        (input_dir / path).parent.mkdir(exist_ok=True, parents=True)
        (input_dir / path).write_bytes(content)

    return _write_spec(
        input_dir=input_dir,
        input_set=input_set,
        nodes=Path(base.path("nodes")).name,
        relationships=Path(base.path("relationships")).name,
    )


# Project construction.
def _build(*, input_dir: Path, project_dir: Path) -> SyntheticProject:
    """Build the pending package for one input set with the production builder.

    Parameters
    ----------
    input_dir
        Input-set directory holding ``package_build.json``.
    project_dir
        Project root.

    Returns
    -------
    SyntheticProject
        Project view of the created package.
    """

    result = build_graph_package(
        dry_run=False,
        settings=BackendSettings(
            graph_packages_root_override=None, project_dir=project_dir
        ),
        spec=PackageBuildSpec.model_validate_json(
            (input_dir / "package_build.json").read_bytes()
        ),
    )
    assert result.outcome == "created"
    return SyntheticProject(
        framework_id=result.manifest.framework_id,
        input_dir=input_dir,
        package_dir=result.package_path,
        project_dir=project_dir,
        snapshot_id=result.manifest.snapshot_id,
    )


def build_synthetic_package(
    *,
    edges_per_type: int = KEPT_EDGES_PER_TYPE,
    input_set: str = SYNTHETIC_INPUT_SET,
    project_dir: Path,
) -> SyntheticProject:
    """Write one synthetic input set into a project and build its pending package.

    Parameters
    ----------
    edges_per_type
        Number of delivered LP edges kept per relationship type.
    input_set
        Input-set directory name under ``data/input_artifacts``.
    project_dir
        Project root that already holds ``config/``.

    Returns
    -------
    SyntheticProject
        Project view of the newly built package.
    """

    spec_path = write_synthetic_input_set(
        edges_per_type=edges_per_type, input_set=input_set, project_dir=project_dir
    )
    return _build(input_dir=spec_path.parent, project_dir=project_dir)


def build_synthetic_project(*, project_dir: Path) -> SyntheticProject:
    """Write a synthetic input set and seal it with the production package builder.

    Parameters
    ----------
    project_dir
        Empty project root; ``config/`` is copied from the repository.

    Returns
    -------
    SyntheticProject
        Project holding the input set and one pending runtime-only package.
    """

    shutil.copytree(REPOSITORY_ROOT / "config", project_dir / "config")
    return build_synthetic_package(project_dir=project_dir)


def copy_synthetic_project(
    *, project_dir: Path, source: SyntheticProject
) -> SyntheticProject:
    """Copy a built synthetic project so one test can alter or persist it.

    Parameters
    ----------
    project_dir
        Destination project root, which must not exist.
    source
        Pristine synthetic project.

    Returns
    -------
    SyntheticProject
        The same layout rooted at ``project_dir``.
    """

    shutil.copytree(source.project_dir, project_dir)
    return SyntheticProject(
        framework_id=source.framework_id,
        input_dir=project_dir / source.input_dir.relative_to(source.project_dir),
        package_dir=project_dir / source.package_dir.relative_to(source.project_dir),
        project_dir=project_dir,
        snapshot_id=source.snapshot_id,
    )


def rebuild_synthetic_package(*, project: SyntheticProject) -> SyntheticProject:
    """Delete a project's built package and build it again from the same spec.

    Parameters
    ----------
    project
        Synthetic project whose package may be replaced.

    Returns
    -------
    SyntheticProject
        Project view of the rebuilt package, whose snapshot may differ.
    """

    shutil.rmtree(project.package_dir)
    return _build(input_dir=project.input_dir, project_dir=project.project_dir)
